// Reimplemented from eve@0.19.0 dist/src/public/channels/telegram/hitl.js
// (Apache-2.0). eve's HITL is STATEFUL: because Telegram caps
// `InlineKeyboardButton.callback_data` at 64 bytes, eve stores a compact
// callback id (`eve:0`, `eve:1`, …) in the button and remaps it back to the
// full `InputResponse` via a durable, per-session channel-state map
// (`hitlCallbacks` / `nextHitlCallbackId`) inside a runtime `deliver` hook.
// trex's channel factory has NO cross-request channel-state store (a route only
// gets `send()`/`resume`; the render and the callback arrive as two separate
// HTTP requests) — the identical constraint the vendored Discord/Slack HITL
// solve by self-encoding the answer into the widget id. So this reimplements the
// render/decode as a STATELESS round-trip: `callback_data` carries the
// requestId+optionId directly (base64url JSON under an `eve:` prefix), staying
// within Telegram's 64-byte cap for typical ids. eve's stateful helpers
// (`registerTelegramCallback`, `resolveTelegramInputResponses`,
// `telegramCallbackInputResponse`, `pendingFreeformReplies`) are NOT vendored.
// See vendor/VENDOR.md.

import { base64UrlToUtf8, type InputRequest, type InputResponse, utf8ToBase64Url } from "./shared.ts";

/** Prefix marking a callback_data value this channel generated. */
export const TELEGRAM_HITL_CALLBACK_PREFIX = "eve:";

/** Telegram inline-keyboard `callback_data` byte cap. */
const TELEGRAM_CALLBACK_DATA_MAX_BYTES = 64;
/** Telegram inline-button label byte budget. */
const TELEGRAM_BUTTON_LABEL_MAX_LENGTH = 64;
/** Guard for the prompt text length. */
const TELEGRAM_PROMPT_MAX_LENGTH = 4000;

/** Rendered Telegram message body for one pending input request. */
export interface TelegramInputRequestMessage {
  /** Set only for optionless (ForceReply) prompts. */
  readonly freeformRequestId?: string;
  readonly replyMarkup?: Readonly<Record<string, unknown>>;
  readonly text: string;
}

/**
 * Renders one `InputRequest` as a Telegram inline keyboard (option requests) or
 * a ForceReply prompt (optionless). Option buttons encode requestId+optionId
 * self-descriptively into `callback_data` so the callback decodes statelessly.
 */
export function renderTelegramInputRequest(request: InputRequest): TelegramInputRequestMessage {
  const options = request.options;
  if (options && options.length > 0) {
    return {
      replyMarkup: {
        inline_keyboard: chunk(
          options.map((o) => ({
            callback_data: encodeTelegramCallbackData(request.requestId, o.id),
            text: truncate(o.label, TELEGRAM_BUTTON_LABEL_MAX_LENGTH),
          })),
          2,
        ),
      },
      text: truncate(request.prompt, TELEGRAM_PROMPT_MAX_LENGTH),
    };
  }
  return {
    freeformRequestId: request.requestId,
    replyMarkup: {
      force_reply: true,
      input_field_placeholder: truncate("Type your answer", 64),
      selective: true,
    },
    text: truncate(request.prompt, TELEGRAM_PROMPT_MAX_LENGTH),
  };
}

/** True when a callback_data value was generated by {@link renderTelegramInputRequest}. */
export function isTelegramHitlCallback(data: string | undefined): data is string {
  return typeof data === "string" && data.startsWith(TELEGRAM_HITL_CALLBACK_PREFIX);
}

/**
 * Encodes a requestId+optionId pair into a `callback_data` value. Throws when
 * the encoding would exceed Telegram's 64-byte cap (unusually long request ids).
 */
export function encodeTelegramCallbackData(requestId: string, optionId: string): string {
  const data = TELEGRAM_HITL_CALLBACK_PREFIX + utf8ToBase64Url(JSON.stringify([requestId, optionId]));
  if (new TextEncoder().encode(data).length > TELEGRAM_CALLBACK_DATA_MAX_BYTES) {
    throw new Error("telegramChannel: encoded HITL callback_data exceeds Telegram's 64-byte limit.");
  }
  return data;
}

/**
 * Decodes a callback_data value produced by {@link encodeTelegramCallbackData}
 * back into an `InputResponse`, or `null` when the value is not ours / malformed.
 */
export function deriveTelegramInputResponse(data: string | undefined): InputResponse | null {
  if (!isTelegramHitlCallback(data)) return null;
  try {
    const decoded = JSON.parse(base64UrlToUtf8(data.slice(TELEGRAM_HITL_CALLBACK_PREFIX.length)));
    if (!Array.isArray(decoded) || decoded.length !== 2) return null;
    const [requestId, optionId] = decoded;
    if (typeof requestId !== "string" || typeof optionId !== "string") return null;
    return { requestId, optionId };
  } catch {
    return null;
  }
}

function truncate(text: string, max: number): string {
  if (text.length <= max) return text;
  const cut = Math.max(0, max - 3);
  return `${text.slice(0, cut).trimEnd()}...`;
}

function chunk<T>(items: readonly T[], size: number): T[][] {
  const out: T[][] = [];
  for (let i = 0; i < items.length; i += size) out.push(items.slice(i, i + size));
  return out;
}
